#include <functional>
#include <gtest/gtest.h>
#include <sstream>
#include <string>

extern "C" {
#include "ast_node.h"
#include "parser.h"
}

#include "ast_printer.hpp"

// Set to 1 to automatically open expected/parsed AST diff tabs in VS Code on
// failure, 0 to disable
#define OPEN_VSCODE_DIFF 0

// Forward declarations of the manual AST builders defined in ast_test.cpp
ast_node_t *build_factorial_program_ast();
ast_node_t *build_strings_program_ast();
ast_node_t *build_algebdt_program_ast();
ast_node_t *build_boolthen_program_ast();
ast_node_t *build_funexp_program_ast();
ast_node_t *build_control_program_ast();
ast_node_t *build_extkw_program_ast();
ast_node_t *build_interpolateds_program_ast();
ast_node_t *build_lambdas_program_ast();
ast_node_t *build_lists_program_ast();
ast_node_t *build_paramlists_program_ast();
ast_node_t *build_valmem_program_ast();

namespace fs = std::filesystem;

struct ParserAstMatchTestCase {
  std::string name;
  std::string scala_filename;
  std::function<ast_node_t *()> build_expected_ast;
};

class ParserAstMatchParamTest
    : public ::testing::TestWithParam<ParserAstMatchTestCase> {
protected:
  std::string expected_file_;
  std::string actual_file_;

  static std::string find_scala_example(const std::string &filename) {
    const std::string examples_dir = "examples";
    if (!fs::exists(examples_dir) || !fs::is_directory(examples_dir)) {
      return "";
    }
    for (const auto &entry : fs::recursive_directory_iterator(examples_dir)) {
      if (entry.is_regular_file() && entry.path().filename() == filename) {
        return entry.path().string();
      }
    }
    return "";
  }

  static std::string read_file_to_string(const std::string &path) {
    std::ifstream ifs(path);
    if (!ifs.is_open()) {
      return "";
    }
    std::ostringstream oss;
    oss << ifs.rdbuf();
    return oss.str();
  }

  void TearDown() override {
#if OPEN_VSCODE_DIFF
    if (HasFailure() && !expected_file_.empty() && !actual_file_.empty()) {
      std::string cmd =
          "code -r --diff \"" + expected_file_ + "\" \"" + actual_file_ + "\"";
      int rc = std::system(cmd.c_str());
      (void)rc;
    }
#endif
  }
};

TEST_P(ParserAstMatchParamTest, MatchesManuallyBuiltAst) {
  const auto &param = GetParam();

  // 1. Locate the corresponding .scala file inside examples/
  std::string scala_path = find_scala_example(param.scala_filename);
  ASSERT_FALSE(scala_path.empty())
      << "Could not find example file '" << param.scala_filename
      << "' anywhere under 'examples/'";

  FILE *stream = std::fopen(scala_path.c_str(), "r");
  ASSERT_NE(stream, nullptr) << "Failed to open file: " << scala_path;

  // 2. Parse the source file into an AST
  ast_node_t *parsed_ast = nullptr;
  err_code_t err = parse(&parsed_ast, stream);
  std::fclose(stream);

  ASSERT_EQ(err, NO_ERR) << "Parser failed on file: " << scala_path;
  ASSERT_NE(parsed_ast, nullptr)
      << "Parser returned null AST for: " << scala_path;

  // 3. Build the expected AST manually
  ast_node_t *expected_ast = param.build_expected_ast();
  ASSERT_NE(expected_ast, nullptr)
      << "Manual AST builder returned null for: " << param.name;

  // 4. Dump both ASTs using ast_printer and compare their serialized
  // representations
  fs::create_directories(".ast_diffs");
  expected_file_ = ".ast_diffs/ParserAstMatch_" + param.name + "_expected.ast";
  actual_file_ = ".ast_diffs/ParserAstMatch_" + param.name + "_parsed.ast";

  dump_ast_to_file(expected_file_.c_str(), expected_ast);
  dump_ast_to_file(actual_file_.c_str(), parsed_ast);

  std::string expected_dump = read_file_to_string(expected_file_);
  std::string actual_dump = read_file_to_string(actual_file_);

  EXPECT_FALSE(expected_dump.empty()) << "Expected AST dump is empty";
  EXPECT_TRUE(actual_dump == expected_dump)
      << "Parsed AST for '" << scala_path << "' does not match manual AST ("
      << param.name << ").\n"
      << "Inspect diff between:\n"
      << "  Expected: " << expected_file_ << "\n"
      << "  Parsed:   " << actual_file_;

  // 5. Cleanup
  destroy_node(parsed_ast);
  destroy_node(expected_ast);
}

